DO $$ DECLARE gh text; ch text; BEGIN SELECT md5(string_agg(concat(a.code,chr(31),g.sort_order,chr(31),g.goal_text),chr(30) ORDER BY a.code,g.sort_order)) INTO gh FROM edu_curriculum_goals g JOIN age_groups a ON a.id=g.age_group_id WHERE g.source_id=(SELECT id FROM edu_curriculum_sources WHERE code='VBHN-01-2021-GDMN'); SELECT md5(string_agg(concat(a.code,chr(31),c.sort_order,chr(31),c.text),chr(30) ORDER BY a.code,c.sort_order)) INTO ch FROM edu_curriculum_contents c JOIN age_groups a ON a.id=c.age_group_id WHERE c.source_id=(SELECT id FROM edu_curriculum_sources WHERE code='VBHN-01-2021-GDMN'); IF gh IS DISTINCT FROM 'e46b3c3406c9bfdf19d3761e9d5a96a7' OR ch IS DISTINCT FROM '299fe3bba307f8859090e123df93c143' THEN RAISE EXCEPTION 'Unexpected catalog baseline text or order'; END IF; END $$;
UPDATE edu_curriculum_goals SET sort_order=sort_order*1000 WHERE source_id=(SELECT id FROM edu_curriculum_sources WHERE code='VBHN-01-2021-GDMN');
