INSERT INTO edu_curriculum_contents (source_id,age_group_id,domain_id,sub_domain_id,category_no,category,label,text,section_ref,sort_order) SELECT c.source_id,a.id,c.domain_id,s.id,c.category_no,c.category,c.label,c.text,c.section_ref,1 FROM edu_curriculum_contents c JOIN age_groups srcage ON srcage.id=c.age_group_id AND srcage.code='ag-3' JOIN age_groups a ON a.code='ag-4' JOIN edu_curriculum_sub_domains origin ON origin.id=c.sub_domain_id JOIN edu_curriculum_sub_domains s ON s.source_id=c.source_id AND s.age_group_id=a.id AND s.domain_id=c.domain_id AND s.text=origin.text WHERE c.source_id=(SELECT id FROM edu_curriculum_sources WHERE code='VBHN-01-2021-GDMN') AND c.sort_order=1000 AND c.text='Hô hấp: Hít vào, thở ra.';
INSERT INTO edu_curriculum_contents (source_id,age_group_id,domain_id,sub_domain_id,category_no,category,label,text,section_ref,sort_order) SELECT c.source_id,a.id,c.domain_id,s.id,c.category_no,c.category,c.label,c.text,c.section_ref,1 FROM edu_curriculum_contents c JOIN age_groups srcage ON srcage.id=c.age_group_id AND srcage.code='ag-3' JOIN age_groups a ON a.code='ag-5' JOIN edu_curriculum_sub_domains origin ON origin.id=c.sub_domain_id JOIN edu_curriculum_sub_domains s ON s.source_id=c.source_id AND s.age_group_id=a.id AND s.domain_id=c.domain_id AND s.text=origin.text WHERE c.source_id=(SELECT id FROM edu_curriculum_sources WHERE code='VBHN-01-2021-GDMN') AND c.sort_order=1000 AND c.text='Hô hấp: Hít vào, thở ra.';
DO $$ BEGIN IF (SELECT count(*) FROM edu_curriculum_contents c JOIN age_groups a ON a.id=c.age_group_id WHERE a.code IN ('ag-4','ag-5') AND c.text='Hô hấp: Hít vào, thở ra.' AND c.sort_order=1) <> 2 THEN RAISE EXCEPTION 'Merged breathing content missing'; END IF; END $$;
